<?php
// Original order queue design: the station's real queue sorted by priority, with the order panel's real actions.
use App\Services\Workspace;
use App\UI\Fulfillment;
use App\UI\LiveForm as F;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$live = Workspace::get()->load(static fn (Workspace $w): array => $w->queue());
if (isset($live['error'])): ?><?= U::heading('Order queue') ?><section class="panel p-6" role="alert"><?= U::e($live['error']) ?></section><?php return; endif;
$orders = array_merge($live['preparing'], $live['queue'], $live['ready'], $live['on_hold'], $live['scheduled'], $live['awaiting_completion']);
// Cancelled orders stay out of the table until the Status filter picks "Cancelled" (rows marked data-filter-only).
$cancelled = $live['cancelled'] ?? [];
$cancelledLabel = S::label('cancelled', 'delivery');
$selectedId = is_string($_GET['order'] ?? null) ? $_GET['order'] : ($orders[0]['id'] ?? null);
$detail = $selectedId ? Workspace::get()->load(static fn (Workspace $w): array => $w->stationOrder($selectedId)) : null;
$sel = $detail && !isset($detail['error']) && !isset($detail['error_code']) ? $detail['order'] : null;
$here = '/station-admin/orders' . ($sel ? '?order=' . $sel['id'] : '');
$count = static fn (callable $test): string => (string) count(array_filter($orders, $test));
$statuses = array_values(array_unique(array_map(static fn (array $o): string => S::label($o['status'], $o['fulfillment']), $orders)));
$kinds = ['overdue' => 'Waiting too long', 'fee_mismatch' => 'Delivery fee check', 'failed_attempt' => 'Failed delivery', 'empties_mismatch' => 'Empty containers differ', 'closure' => 'Station closure', 'capacity' => 'Too big for vehicles'];
?>
<div data-poll-url="/station-admin/orders/updates" data-poll-version="<?= U::e(Workspace::fingerprint(array_diff_key($live, ['cancelled' => true]))) ?>" data-poll-seconds="30" hidden></div>
<?= U::heading('Order queue','Manage orders for '.$info['caption'].'. Positions follow priority and are estimates.',$sel ? U::btn('Message customer','/station-admin/messages?customer='.$sel['customer_id'],'secondary','message') : '') ?>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Active orders',(string) count($orders),'orders','blue','In the queue today','Active') ?><?= U::stat('Preparing',$count(fn($o)=>$o['status']==='preparing'),'clock','amber','Being refilled now','Prep') ?><?= U::stat('Ready',$count(fn($o)=>$o['status']==='ready'),'check','green','Waiting for rider or customer','Ready') ?><?= U::stat('Pickup orders',$count(fn($o)=>$o['fulfillment']==='pickup'),'store','violet','Collected at the station','Pickup') ?></div>
<?php foreach ($live['reviews'] as $rv): ?><div class="mb-3 flex flex-wrap items-center gap-3 rounded-xl border border-amber-200 bg-amber-50 px-3.5 py-2.5 text-sm text-amber-900"><?= U::icon('alert','size-4 shrink-0') ?><span class="flex-1"><a class="font-bold underline" href="/station-admin/orders?order=<?= U::e($rv['order_id']) ?>"><?= U::e($rv['order_no'] ?? '') ?></a> · <?= U::e($kinds[$rv['kind']] ?? $rv['kind']) ?>: <?= U::e($rv['detail']) ?></span><?php if (!in_array($rv['kind'], ['failed_attempt','fee_mismatch'], true)): ?><?= F::reason('/station-admin/reviews/resolve', ['review_id' => $rv['id'], 'expected_version' => $rv['version'], 'back' => $here], 'Resolution', 'Prepared next; customer informed', 'Resolve') ?><?php endif ?></div><?php endforeach ?>
<div class="grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><section class="panel p-4 md:p-5"><div class="mb-4 grid gap-3 sm:grid-cols-3"><?= U::field('Search orders','order-search','','search',['icon'=>'search','data-search'=>'station-orders','placeholder'=>'Order, customer or barangay']) ?><?= U::select('Status','status',['all'=>'All statuses'] + array_combine($statuses, $statuses) + [$cancelledLabel => $cancelledLabel],'all',['data-filter-target'=>'station-orders']) ?><?= U::select('Fulfillment','fulfillment',['all'=>'All methods','delivery'=>'Delivery','pickup'=>'Pickup'],'all',['data-filter-target'=>'station-orders','data-filter-key'=>'fulfillment']) ?></div>
<div class="overflow-x-auto"><table id="station-orders" class="data-table"><thead><tr><?php foreach(['Order','Customer','Qty','Priority','Method','Status','Action'] as $h): ?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($orders as $o): $label = S::label($o['status'], $o['fulfillment']); ?><tr data-search-row data-fulfillment="<?= U::e($o['fulfillment']) ?>" data-filter-value="<?= U::e($label) ?>"><td class="whitespace-nowrap font-bold"><?= U::e($o['order_no']) ?><?= $o['overdue'] ? ' '.U::badge('Overdue','red') : '' ?></td><td><span class="block font-medium"><?= U::e($o['customer_name'] ?? '') ?></span><span class="flex items-center gap-1 text-xs text-muted"><?= U::icon('pin','size-3.5') ?><?= U::e($o['barangay'] ?? 'Pickup') ?></span></td><td><span class="inline-flex items-center gap-1"><?= U::icon('bottle','size-4 text-water') ?><?= (int) $o['total_units'] ?></span></td><td><span class="inline-flex min-w-9 justify-center rounded-md bg-ink px-2 py-0.5 text-xs font-bold text-white" title="Urgency <?= (int) $o['score']['u'] ?> + waiting <?= (int) $o['score']['a'] ?> + customer <?= (int) $o['score']['c'] ?>"><?= (int) $o['score']['p'] ?></span></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon($o['fulfillment']==='pickup'?'store':'truck','size-4 text-water') ?><?= U::e(Fulfillment::label($o['fulfillment'])) ?></span></td><td><?= U::badge($label, S::tone($o['status'])) ?></td><td><?= U::btn('View','/station-admin/orders?order='.$o['id'],'secondary','eye',['class'=>'btn-sm']) ?></td></tr><?php endforeach ?><?php foreach($cancelled as $o): ?><tr data-search-row data-filter-only hidden data-fulfillment="<?= U::e($o['fulfillment']) ?>" data-filter-value="<?= U::e($cancelledLabel) ?>"><td class="whitespace-nowrap font-bold"><?= U::e($o['order_no']) ?></td><td><span class="block font-medium"><?= U::e($o['customer_name'] ?? '') ?></span><span class="flex items-center gap-1 text-xs text-muted"><?= U::icon('pin','size-3.5') ?><?= U::e($o['barangay'] ?? 'Pickup') ?></span></td><td><span class="inline-flex items-center gap-1"><?= U::icon('bottle','size-4 text-water') ?><?= (int) $o['total_units'] ?></span></td><td><span class="text-muted" title="Cancelled orders have no queue priority">—</span></td><td><span class="inline-flex items-center gap-1.5"><?= U::icon($o['fulfillment']==='pickup'?'store':'truck','size-4 text-water') ?><?= U::e(Fulfillment::label($o['fulfillment'])) ?></span></td><td><?= U::badge($cancelledLabel, S::tone('cancelled')) ?><?= ($o['cancel_reason'] ?? '') !== '' ? '<span class="mt-1 block max-w-48 truncate text-xs text-muted" title="' . U::e($o['cancel_reason']) . '">' . U::e($o['cancel_reason']) . '</span>' : '' ?></td><td><?= U::btn('View','/station-admin/orders?order='.$o['id'],'secondary','eye',['class'=>'btn-sm']) ?></td></tr><?php endforeach ?></tbody></table><p <?= $orders === [] ? '' : 'hidden' ?> data-empty class="p-5 muted"><?= $orders === [] ? 'No orders in the queue right now.' : 'No matching orders.' ?></p></div></section>
<aside class="panel h-fit p-4 md:p-5"><?php if ($sel === null): ?><?= U::title('Order details','orders') ?><p class="mt-2 text-sm text-muted">Choose an order to see its details and actions.</p><?php else: $pay = $detail['payment']; $f = ['order_id' => $sel['id'], 'expected_version' => $sel['version'], 'back' => $here]; $pickup = $sel['fulfillment'] === 'pickup'; ?>
<?= U::title($sel['order_no'],'orders') ?><p class="mt-1 flex items-center gap-1.5 text-sm text-muted"><?= U::icon('user','size-4') ?><?= U::e($sel['contact_name'] ?? '') ?>, <?= U::e($pickup ? 'Pickup' : ($sel['address_barangay'] ?? '')) ?></p><div class="my-3"><?= S::badge($sel['status'], $sel['fulfillment']) ?></div>
<dl class="space-y-1.5 text-sm"><?php foreach ([[$pickup?'store':'truck','Fulfillment',Fulfillment::label($sel['fulfillment'])],['bottle','Items',implode(', ', array_map(static fn (array $i): string => $i['quantity'].' × '.$i['name'], $detail['items']))],['tag','Order total',S::pesos($sel['total_centavos'])],['credit','Payment',$pickup ? 'Cash on pickup' : 'Cash on delivery'],['phone','Contact',(string) ($sel['contact_phone'] ?? '')]] as [$icon,$dt,$dd]): ?><div class="flex items-center justify-between gap-3 rounded-lg bg-mist px-3 py-2"><dt class="flex items-center gap-2 text-muted"><?= U::icon($icon,'size-4 text-water') ?><?= U::e($dt) ?></dt><dd class="text-right font-medium"><?= U::e($dd) ?></dd></div><?php endforeach ?><div class="flex items-center justify-between rounded-lg bg-water px-3 py-2 font-bold text-white"><dt class="flex items-center gap-2"><?= U::icon('chart','size-4') ?>Priority score</dt><dd><?= (int) $detail['score']['p'] ?></dd></div></dl>
<p class="my-3 flex items-start gap-2 text-xs text-muted"><?= U::icon('refresh','size-4 shrink-0') ?><?= U::e(!$pickup ? ($sel['address_text'] ?? '') . ($sel['note'] !== '' ? ' · Note: ' . $sel['note'] : '') : ($sel['note'] !== '' ? 'Note: ' . $sel['note'] : 'Customer collects at the station. Bring empty containers for exchange.')) ?></p>
<div class="grid grid-cols-2 gap-2"><?php if (in_array($sel['status'], ['pending','confirmed'], true)): ?><?= F::button('/station-admin/orders/start', $f, 'Start preparing', 'primary', 'check', null, 'whitespace-nowrap px-3 w-full') ?><?php endif ?><?php if ($sel['status'] === 'preparing'): ?><?= F::button('/station-admin/orders/ready', $f, 'Mark ready', 'secondary', 'check', null, 'whitespace-nowrap px-3 w-full') ?><?php endif ?><?php if (in_array($sel['status'], ['delivered','collected'], true)): ?><?= F::button('/station-admin/orders/complete', $f, 'Complete', 'primary', 'check', null, 'whitespace-nowrap px-3 w-full') ?><?php endif ?></div>
<?php if ($pay !== null && $pay['state'] === 'unverified'): ?><div class="mt-2 rounded-lg bg-foam p-3 text-xs">Cash: <?= S::pesos($pay['applied_centavos']) ?> applied · <?= S::pesos($pay['tendered_centavos']) ?> received · <?= S::pesos($pay['change_centavos']) ?> change · empties <?= (int) $pay['empties_returned'] ?>/<?= (int) $pay['expected_empties'] ?><div class="mt-2"><?= F::button('/station-admin/payments/verify', ['payment_id' => $pay['id'], 'expected_version' => $pay['version'], 'back' => $here], 'Verify cash', 'secondary', 'credit', null, 'w-full') ?></div></div><?php endif ?>
<?php foreach ($detail['reviews'] as $rv): if ($rv['state'] !== 'open') continue; ?><div class="mt-2 rounded-lg bg-amber-50 p-3 text-xs text-amber-900"><p class="font-semibold"><?= U::e($kinds[$rv['kind']] ?? $rv['kind']) ?>: <?= U::e($rv['detail']) ?></p><div class="mt-2"><?= $rv['kind'] === 'fee_mismatch' ? F::reason('/station-admin/orders/fee-review', $f, 'Why the quoted fee stands', 'Pin is correct', 'Save') : ($rv['kind'] === 'failed_attempt' ? F::reason('/station-admin/orders/reattempt', $f, 'Why another try will work', 'Customer is home now', 'Approve reattempt') : F::reason('/station-admin/reviews/resolve', ['review_id' => $rv['id'], 'expected_version' => $rv['version'], 'back' => $here], 'Resolution', 'Done', 'Resolve')) ?></div></div><?php endforeach ?>
<?= $pickup ? U::btn('Open pickup queue','/station-admin/pickups','ghost','store',['class'=>'mt-2 w-full']) : U::btn('Open dispatch','/station-admin/deliveries#dispatch','ghost','truck',['class'=>'mt-2 w-full']) ?>
<?php if (in_array($sel['status'], ['pending','on_hold','scheduled','confirmed','preparing'], true) || ($sel['status'] === 'ready' && $pay === null)): ?><details class="mt-2 text-sm"><summary class="cursor-pointer font-semibold text-rose-700">Cancel this order</summary><div class="mt-2"><?= F::reason('/station-admin/orders/cancel', $f, 'Reason (sent to the customer)', 'Out of containers today', 'Cancel order', 'secondary', 'Cancel this order? The customer will be notified.') ?></div></details><?php endif ?>
<?php endif ?></aside></div>
